head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gAcptNo;
scwin.gViewerStat = "P"; // 처리시 뷰어=P,  조회시 뷰어=R

scwin.gParamObj = new Array(5);
scwin.vScrenID = "ULDSTF30606.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Search = function() {
    var vISUR_CD = $c.stf.getQuery(frame.srcUrl, "ISUR_CD");
    var vCOM_NM = $c.stf.getQuery(frame.srcUrl, "COM_NM");
    var vSTKCERT_LIST_DD = $c.stf.getQuery(frame.srcUrl, "STKCERT_LIST_DD");
    $c.stf.setObjectValue(txb_ISUR_CD, vISUR_CD);
    $c.stf.setObjectValue(txb_COM_NM, vCOM_NM);
    $c.stf.setObjectValue(txb_STKCERT_LIST_DD, vSTKCERT_LIST_DD);
    var url = "/ListedCompany.do?method=readCompanyPersonInChargeEducationCompletionAto";
    url += "&ISUR_CD=" + vISUR_CD;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Grid1.DataID = encodeURI(url);
    dts_Grid1.Reset();
    var url = "/ListedCompany.do?method=readCompanyPersonInChargeEducationCompletion2";
    url += "&ISUR_CD=" + vISUR_CD;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Grid2.DataID = encodeURI(url);
    dts_Grid2.Reset();
    var url = "/ListedCompany.do?method=readCompanyPersonInChargeEducationCompletion3";
    url += "&ISUR_CD=" + vISUR_CD;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Grid3.DataID = encodeURI(url);
    dts_Grid3.Reset();
};
scwin.fn_read = async function(GridID, row, colid) {
    //작업해야함 
    var objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..		
    var CMD = "R";
    if (row < 1) return;

    //OPEN 
    if (colid == "REMINDER_YN") {
        //상세화면 
        var vISUR_CD = objDataID.getCellData(row, "ISUR_CD");
        var vEDU_KIND_CD = objDataID.getCellData(row, "EDU_KIND_CD");
        var vEDU_KIND_CDNM = objDataID.getCellData(row, "EDU_KIND_CDNM");
        var vREMINDER_YN = objDataID.getCellData(row, "REMINDER_YN");
        var vEDU_PARTC_ID = objDataID.getCellData(row, "EDU_PARTC_ID");
        if (js_market == '6') vEDU_KIND_CD = '81';
        var CMD = "R";
        if (vREMINDER_YN != '') {
            if (scwin.fn_setParam(CMD, vISUR_CD, vEDU_KIND_CD, vEDU_KIND_CDNM, vEDU_PARTC_ID)) // formal arguments

            {
                await $c.frame.CreateDialogFrame("child01", "/issueinfo/ULDSTF30609.gfm", "세부교육이수현황", 200, 200, 450, 190, "window");
            }
        }
    }
};
scwin.fn_setParam = function() {
    // child에 param을 넘긴다.
    if (typeof(scwin.gParamObj) == "undefined") {
        $c.win.alert("전역변수 gParamObj를 선언하세요.");
        return false;
    }
    var argv = fn_setParam.arguments;
    var argc = fn_setParam.arguments.length;
    scwin.gParamObj = new Array(argc); // 초기화
    for (var i = 0; i < argc; i++) // actual arguments

    {
        eval("gParamObj.param" + i + " = argv[" + i + "]");
    }
    return true;
};
scwin.grd_Grid1_OnDblClick = function(row, colid) {
    scwin.fn_read(grd_Grid1, row, colid);
};
scwin.dts_Grid1_OnLoadCompleted = function(rowcount) {

};
scwin.dts_Grid1_OnLoadError = function() {

};
scwin.grd_Grid3_OnDblClick = function(row, colid) {
    if (colid == "ACPT_NO") {
        var AcptNo = dts_Grid3.getCellData(row, "ACPT_NO");
        $c.stf.fn_OpenDisclViewer(AcptNo, "R");
    }
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_Search();
};
